<?php
namespace ExcelHerbal\ERP7\Sales;
use ExcelHerbal\ERP7\Core\NumberSeries;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Finance\AccountingService;use ExcelHerbal\ERP7\Finance\BranchDayGuard;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class SalesService{
 public static function customers(Actor $a,int $branch):array{Guard::any($a,[Capabilities::SALES_VIEW,Capabilities::SALES_CREATE,Capabilities::RECEIPT_CREATE]);if(!$a->hasBranch($branch))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT id,name,mobile,email,address FROM ".Db::table('parties')." WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' ORDER BY name",$a->companyId,$branch),ARRAY_A);}
 public static function availableStock(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::SALES_CREATE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT sb.product_id,sb.batch_key,sb.quantity,p.name product_name,p.uom,p.batch_tracking,b.batch_no,b.expires_on FROM ".Db::table('stock_balances')." sb JOIN ".Db::table('products')." p ON p.id=sb.product_id LEFT JOIN ".Db::table('batches')." b ON b.id=NULLIF(sb.batch_key,0) WHERE sb.company_id=%d AND sb.branch_id=%d AND sb.custodian_key=0 AND sb.quantity>0 ORDER BY p.name,b.expires_on,b.batch_no",$a->companyId,$branch),ARRAY_A);}
 public static function openSales(Actor $a,int $branch,?int $customer=null):array{
  Guard::branch($a,$branch,Capabilities::RECEIPT_CREATE);
  $db=Db::wpdb();$where='s.company_id=%d AND s.branch_id=%d AND s.status=\'posted\' AND s.outstanding_amount>0 AND s.customer_id IS NOT NULL';$args=[$a->companyId,$branch];
  if($customer){$where.=' AND s.customer_id=%d';$args[]=$customer;}
  return(array)$db->get_results($db->prepare("SELECT s.id,s.sale_no,s.sale_date,s.customer_id,p.name customer_name,s.gross_amount,s.paid_amount,s.outstanding_amount FROM ".Db::table('counter_sales')." s JOIN ".Db::table('parties')." p ON p.id=s.customer_id AND p.company_id=s.company_id WHERE {$where} ORDER BY s.sale_date,s.id",...$args),ARRAY_A);
 }
 public static function createCustomer(Actor $a,int $branch,string $name,string $mobile='',string $email='',string $address=''):array{
  Guard::branch($a,$branch,Capabilities::SALES_CREATE);$name=trim($name);$mobile=preg_replace('/\\D+/','',$mobile)?:'';$email=trim($email);$address=trim($address);
  if($name===''||strlen($name)>190)throw new DomainException('Valid customer name is required.','customer_fields_invalid',422);if($mobile!==''&&(strlen($mobile)<8||strlen($mobile)>15))throw new DomainException('Customer mobile must contain 8 to 15 digits.','mobile_invalid',422);if($email!==''&&(!is_email($email)||strlen($email)>190))throw new DomainException('Valid customer email is required.','email_invalid',422);
  return Transaction::run(function()use($a,$branch,$name,$mobile,$email,$address){
   $db=Db::wpdb();$branchTable=Db::table('branches');$locked=(int)$db->get_var($db->prepare("SELECT id FROM {$branchTable} WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$branch,$a->companyId));if(!$locked)throw new DomainException('Active branch not found.','branch_not_found',404);$t=Db::table('parties');
   if($mobile!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND mobile=%s",$a->companyId,$branch,$mobile)))throw new DomainException('An active customer already uses this mobile number.','customer_duplicate',409);
   if($email!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND LOWER(email)=LOWER(%s)",$a->companyId,$branch,$email)))throw new DomainException('An active customer already uses this email address.','customer_duplicate',409);
   Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'type'=>'customer','name'=>$name,'mobile'=>$mobile?:null,'email'=>$email?:null,'address'=>$address?:null,'status'=>'active','created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'customer.create','customer',$id,['branch_id'=>$branch]);return['id'=>$id,'name'=>$name,'status'=>'active'];
  });
 }
 public static function counter(Actor $a,int $branch,?int $customer,float $paid,?int $paymentAccount,array $lines):array{Guard::branch($a,$branch,Capabilities::SALES_CREATE);BranchDayGuard::assertOpen($a,$branch,Db::today());if(!$lines)throw new DomainException('Sale needs product lines.');$prepared=[];$gross=0.0;$cogs=0.0;$seen=[];foreach($lines as$x){$pid=(int)($x['product_id']??0);$batch=isset($x['batch_id'])?(int)$x['batch_id']:null;$qty=(float)($x['quantity']??0);if(!$pid||$qty<=0)throw new DomainException('Invalid sale line.');$key=$pid.'|'.($batch?:0);if(isset($seen[$key]))throw new DomainException('Duplicate sale product/batch line.','duplicate_sale_line',422);$seen[$key]=1;$p=StockService::product($a,$pid);StockService::validateBatch($a,$p,$batch,true);$c=StockService::commercial($a,$pid);$cost=StockService::cost($a,$branch,$pid,$batch,null);$amount=round($qty*(float)$c['sale_price'],2);$gross+=$amount;$cogs+=round($qty*$cost,2);$prepared[]=['product_id'=>$pid,'batch_id'=>$batch,'quantity'=>$qty,'unit_price'=>(float)$c['sale_price'],'line_total'=>$amount,'points'=>(float)$c['points'],'salary'=>(float)$c['salary_fund'],'cost'=>$cost];}$gross=round($gross,2);$paid=round($paid,2);if($paid<0||$paid>$gross)throw new DomainException('Invalid paid amount.');$out=round($gross-$paid,2);if($out>0&&!$customer)throw new DomainException('Customer required for credit sale.','customer_required_for_credit',422);if($customer){$ok=(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT COUNT(*) FROM ".Db::table('parties')." WHERE id=%d AND company_id=%d AND branch_id=%d AND type='customer' AND status='active'",$customer,$a->companyId,$branch));if(!$ok)throw new DomainException('Active customer not found in selected branch.','customer_invalid',422);}if($paid>0){if(!$paymentAccount)throw new DomainException('Payment account required.');AccountingService::paymentAccount($a,$paymentAccount);}
  return Transaction::run(function()use($a,$branch,$customer,$paid,$paymentAccount,$prepared,$gross,$out,$cogs){$db=Db::wpdb();$h=Db::table('counter_sales');$no=NumberSeries::next($a->companyId,'counter_sale','CS-');Db::mustInsert($db,$h,['company_id'=>$a->companyId,'branch_id'=>$branch,'customer_id'=>$customer,'sale_no'=>$no,'sale_date'=>Db::now(),'status'=>'posted','gross_amount'=>$gross,'paid_amount'=>$paid,'outstanding_amount'=>$out,'payment_account_id'=>$paymentAccount,'created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;foreach($prepared as$l){Db::mustInsert($db,Db::table('counter_sale_lines'),['sale_id'=>$id,'product_id'=>$l['product_id'],'batch_id'=>$l['batch_id'],'quantity'=>$l['quantity'],'unit_price'=>$l['unit_price'],'line_total'=>$l['line_total'],'points_snapshot'=>$l['points'],'salary_fund_snapshot'=>$l['salary'],'purchase_cost_snapshot'=>$l['cost']]);StockService::move($a,$branch,$l['product_id'],$l['batch_id'],null,'OUT',$l['quantity'],$l['cost'],'counter_sale',$id);} $sales=AccountingService::accountByCode($a,'SALES');$cogsA=AccountingService::accountByCode($a,'COGS');$inv=AccountingService::accountByCode($a,'INVENTORY');$jl=[];if($paid>0)$jl[]=['account_id'=>$paymentAccount,'debit'=>$paid];if($out>0){$ar=AccountingService::accountByCode($a,'AR');$jl[]=['account_id'=>(int)$ar['id'],'debit'=>$out,'party_type'=>'customer','party_id'=>$customer];}$jl[]=['account_id'=>(int)$sales['id'],'credit'=>$gross];if($cogs>0){$jl[]=['account_id'=>(int)$cogsA['id'],'debit'=>$cogs];$jl[]=['account_id'=>(int)$inv['id'],'credit'=>$cogs];}$journal=AccountingService::post($a,$branch,'counter_sale',$id,Db::businessNow(),$jl,'Counter sale '.$no);Db::mustUpdate($db,$h,['journal_entry_id'=>$journal],['id'=>$id]);Audit::add($a,'counter_sale.post','counter_sale',$id,['branch_id'=>$branch,'amount'=>$gross]);return['id'=>$id,'sale_no'=>$no,'gross_amount'=>$gross,'paid_amount'=>$paid,'outstanding_amount'=>$out,'status'=>'posted'];});}
 public static function receipt(Actor $a,int $branch,int $saleId,float $amount,int $account,string $reference):array{
  Guard::branch($a,$branch,Capabilities::RECEIPT_CREATE);BranchDayGuard::assertOpen($a,$branch,Db::today());
  $amount=round($amount,2);if($amount<=0)throw new DomainException('Receipt must be positive.');
  AccountingService::paymentAccount($a,$account);
  return Transaction::run(function()use($a,$branch,$saleId,$amount,$account,$reference){
   $db=Db::wpdb();$sales=Db::table('counter_sales');
   $sale=$db->get_row($db->prepare("SELECT * FROM {$sales} WHERE id=%d AND company_id=%d AND branch_id=%d AND status='posted' FOR UPDATE",$saleId,$a->companyId,$branch),ARRAY_A);
   if(!$sale)throw new DomainException('Posted sale not found in selected branch.','sale_not_found',404);
   $customer=(int)($sale['customer_id']??0);if($customer<1)throw new DomainException('Receipt requires a registered customer sale.','receipt_customer_required',422);
   $outstanding=round((float)$sale['outstanding_amount'],2);if($outstanding<=0)throw new DomainException('Selected sale has no outstanding amount.','sale_not_outstanding',409);
   if($amount>$outstanding+.005)throw new DomainException('Receipt exceeds selected sale outstanding; customer advance is disabled.','customer_advance_disabled',409);
   $t=Db::table('customer_receipts');
   Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'customer_id'=>$customer,'sale_id'=>$saleId,'amount'=>$amount,'payment_account_id'=>$account,'reference'=>trim($reference)?:null,'status'=>'posted','received_by'=>$a->employeeId,'received_at'=>Db::now()]);
   if(!$db->insert_id)throw new DomainException('Customer receipt could not be recorded.','customer_receipt_insert_failed',500);
   $id=(int)$db->insert_id;
   Db::mustQuery($db,$db->prepare("UPDATE {$sales} SET paid_amount=paid_amount+%f,outstanding_amount=outstanding_amount-%f WHERE id=%d",$amount,$amount,$saleId));
   $ar=AccountingService::accountByCode($a,'AR');
   $journal=AccountingService::post($a,$branch,'customer_receipt',$id,Db::businessNow(),[['account_id'=>$account,'debit'=>$amount],['account_id'=>(int)$ar['id'],'credit'=>$amount,'party_type'=>'customer','party_id'=>$customer]],'Customer receipt for sale '.(string)$sale['sale_no']);
   Db::mustUpdate($db,$t,['journal_entry_id'=>$journal],['id'=>$id]);
   Audit::add($a,'customer_receipt.post','customer_receipt',$id,['branch_id'=>$branch,'sale_id'=>$saleId,'customer_id'=>$customer,'amount'=>$amount]);
   return['id'=>$id,'sale_id'=>$saleId,'customer_id'=>$customer,'amount'=>$amount,'remaining_outstanding'=>round($outstanding-$amount,2),'status'=>'posted'];
  });
 }

 public static function updateCustomer(Actor $a,int $customerId,array $data):array{
  return Transaction::run(function()use($a,$customerId,$data){
   $db=Db::wpdb();$t=Db::table('parties');$c=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND type='customer' FOR UPDATE",$customerId,$a->companyId),ARRAY_A);if(!$c)throw new DomainException('Customer not found.','customer_not_found',404);Guard::branch($a,(int)$c['branch_id'],Capabilities::SALES_CREATE);$branchTable=Db::table('branches');$db->get_var($db->prepare("SELECT id FROM {$branchTable} WHERE id=%d AND company_id=%d FOR UPDATE",(int)$c['branch_id'],$a->companyId));$chg=[];
   if(array_key_exists('name',$data)){$v=trim((string)$data['name']);if($v===''||strlen($v)>190)throw new DomainException('Valid customer name is required.','customer_fields_invalid',422);$chg['name']=$v;}
   if(array_key_exists('mobile',$data)){$v=preg_replace('/\\D+/','',(string)$data['mobile'])?:'';if($v!==''&&(strlen($v)<8||strlen($v)>15))throw new DomainException('Customer mobile must contain 8 to 15 digits.','mobile_invalid',422);if($v!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND mobile=%s AND id<>%d",$a->companyId,(int)$c['branch_id'],$v,$customerId)))throw new DomainException('An active customer already uses this mobile number.','customer_duplicate',409);$chg['mobile']=$v?:null;}
   if(array_key_exists('email',$data)){$v=trim((string)$data['email']);if($v!==''&&(!is_email($v)||strlen($v)>190))throw new DomainException('Valid customer email is required.','email_invalid',422);if($v!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND LOWER(email)=LOWER(%s) AND id<>%d",$a->companyId,(int)$c['branch_id'],$v,$customerId)))throw new DomainException('An active customer already uses this email address.','customer_duplicate',409);$chg['email']=$v?:null;}
   if(array_key_exists('address',$data))$chg['address']=trim((string)$data['address'])?:null;if(!$chg)throw new DomainException('No editable customer fields supplied.','parameter_required',422);Db::mustUpdate($db,$t,$chg,['id'=>$customerId,'company_id'=>$a->companyId]);Audit::add($a,'customer.update','customer',$customerId,['branch_id'=>(int)$c['branch_id'],'fields'=>array_keys($chg)]);return['id'=>$customerId]+$chg+['status'=>(string)$c['status']];
  });
 }
 public static function setCustomerStatus(Actor $a,int $customerId,bool $active):array{
  return Transaction::run(function()use($a,$customerId,$active){
   $db=Db::wpdb();$t=Db::table('parties');$c=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND type='customer' FOR UPDATE",$customerId,$a->companyId),ARRAY_A);if(!$c)throw new DomainException('Customer not found.','customer_not_found',404);Guard::branch($a,(int)$c['branch_id'],Capabilities::SALES_CREATE);$branchTable=Db::table('branches');$db->get_var($db->prepare("SELECT id FROM {$branchTable} WHERE id=%d AND company_id=%d FOR UPDATE",(int)$c['branch_id'],$a->companyId));$target=$active?'active':'inactive';
   if($active){$mobile=trim((string)($c['mobile']??''));$email=trim((string)($c['email']??''));if($mobile!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND mobile=%s AND id<>%d",$a->companyId,(int)$c['branch_id'],$mobile,$customerId)))throw new DomainException('Another active customer already uses this mobile number.','customer_duplicate',409);if($email!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND branch_id=%d AND type='customer' AND status='active' AND LOWER(email)=LOWER(%s) AND id<>%d",$a->companyId,(int)$c['branch_id'],$email,$customerId)))throw new DomainException('Another active customer already uses this email address.','customer_duplicate',409);}
   Db::mustUpdate($db,$t,['status'=>$target],['id'=>$customerId,'company_id'=>$a->companyId]);Audit::add($a,'customer.status','customer',$customerId,['branch_id'=>(int)$c['branch_id'],'status'=>$target]);return['id'=>$customerId,'status'=>$target];
  });
 }


}
